{
  "name": "ambroke",
  "spawnLocation": 1,
  "startingItems": ["clasp-knife", "oilskin coat"],

  "items": [
    {
      "name": "clasp-knife",
      "description": "A fisherman's clasp-knife, the blade worn narrow by sharpening. Yours, apparently.",
      "kind": "weapon",
      "attackBonus": 0,
      "attackDice": 4
    },
    {
      "name": "oilskin coat",
      "description": "Stiff, black, smelling of tar and old weather. It has kept somebody dry for years.",
      "kind": "armor",
      "armorClassBonus": 1
    },
    {
      "name": "stopped apple",
      "description": "Small, green-red, and cold as a stone from a stream. The rain on its skin has not moved since you picked it.",
      "kind": "consumable",
      "healAmount": 8,
      "consumedOnUse": true
    },
    {
      "name": "drowned lamp",
      "description": "A keeper's storm-lamp, brass gone green, the glass whole. There is still oil in it. It has been down that well a long time and it is still, somehow, ready.",
      "kind": "misc"
    },
    {
      "name": "oar",
      "description": "One oar from Ambroke's last boat, worn thin where two hands went. It will get you out of here if you mean it.",
      "kind": "misc",
      "isKey": true
    },
    {
      "name": "grey feather",
      "description": "A long grey feather. You took it off something that was only standing there.",
      "kind": "misc"
    }
  ],

  "monsters": [
    {
      "name": "grey heron",
      "description": "A grey heron stands at the end of the quay, one leg drawn up, watching you with an eye like a bead of amber. It is taller than you thought a heron was. Its bill is a spear and it has not blinked.",
      "hitPoints": 12,
      "armorClass": 15,
      "attackStrength": 2,
      "attackDice": 4,
      "inventory": ["grey feather"],
      "respawnSeconds": 900
    }
  ],

  "locations": [
    {
      "index": 1,
      "name": "The Shingle",
      "description": "Black stones, wet and clicking, run down to where the sea should be. The sea is not where it should be: east of the village it stands upright, a green wall of water three houses high, holding still as glass. The light that comes through it is aquarium light, and it lies on everything.\n\nYou are not drowned. That appears to have been somebody's decision.\n\nA board has been nailed to a post at the head of the path.",
      "connections": { "north": 2 },
      "interactions": [
        {
          "interactionId": "shingle-board",
          "triggers": ["read the board", "*read the board*", "*the board*", "read the sign", "*the post*"],
          "actions": [
            {
              "action": "describe",
              "parameters": ["Burnt into the wood, in a hand that pressed hard:\n\n  SPEAK PLAINLY. THE PLACE IS LISTENING.\n  GO NORTH.\n  LOOK AT THINGS. TAKE WHAT YOU NEED.\n  RING THE BELL. READ THE NAMES.\n  LIGHT THE LAMP LAST.\n\nUnderneath, smaller, not burnt but scratched with a nail:\n  i did them out of order. dont."]
            }
          ]
        },
        {
          "interactionId": "shingle-wave",
          "triggers": ["touch the wave", "*touch the wave*", "*touch the water*", "swim", "*enter the wave*"],
          "actions": [
            {
              "action": "describe",
              "parameters": ["From here the wave is a quarter-mile off and the length of the village wide. You could walk to it. People have: there is a track of footprints going out over the sand that the sea forgot to take back, and it stops, and it does not come back."]
            }
          ]
        }
      ]
    },

    {
      "index": 2,
      "name": "Ambroke Lane",
      "description": "One street of grey stone houses with their doors standing open. Nobody has gone through those doorways in a long while — the dust on the sills is unmarked, and lies thick and even, like something that has been allowed to finish.\n\nNothing here is broken. That is worse than if it were.\n\nNorth stands a squat tower. East, a schoolhouse with its windows steamed on the inside. West, an orchard wall.",
      "connections": { "north": 3, "east": 4, "west": 5, "south": 1 },
      "interactions": [
        {
          "interactionId": "lane-houses",
          "triggers": ["enter a house", "*go into a house*", "*the doors*", "*the houses*", "knock", "*knock on*", "*look inside*"],
          "actions": [
            {
              "action": "describe",
              "parameters": ["The nearest house: a table laid for four, a pot gone cold and then gone dry, a chair pushed back and never pushed in. No bodies. Not in this one, not in the next, not in any of them.\n\nWhatever happened to Ambroke, everybody heard it coming, and everybody went outside."]
            }
          ]
        }
      ]
    },

    {
      "index": 3,
      "name": "The Bell Tower",
      "description": "Inside the tower it smells of rope and salt. The bell hangs in its frame above you, mouth down, big as a bathtub. The rope comes to a stop at chest height, spliced and waiting, with old grease on it where hands went.\n\nThrough the eastern arch: the quay, and above the quay, the standing wave.",
      "connections": { "south": 2, "east": 6 },
      "interactions": [
        {
          "interactionId": "bell-return",
          "if": ["wave_fallen"],
          "triggers": ["ring the bell", "ring bell", "*ring the bell*", "pull the rope", "pull rope", "*pull the rope*", "toll the bell", "*toll the bell*"],
          "actions": [
            {
              "action": "describe",
              "parameters": ["You take the rope in both hands and pull, and the bell says one enormous word.\n\nOut past the quay the sea gathers itself, stands up, and stops — three houses high, green as glass, holding. The lamp in its hook on the quay goes out with a small click. In the orchard the rain halts in the air, each drop a bead of nothing falling. The dust settles back onto the sills as though it had been asked politely.\n\nAmbroke is asleep again, and waiting for somebody else.\n\nYou can still leave. The boat is under the wave, where it always was."]
            },
            { "action": "removecondition", "parameters": ["wave_fallen"] },
            { "action": "removecondition", "parameters": ["bell_rung"] },
            { "action": "removecondition", "parameters": ["names_read"] },
            { "action": "removecondition", "parameters": ["lamp_lit"] },
            {
              "action": "setlocationdescription",
              "parameters": ["1", "Black stones, wet and clicking, run down to where the sea should be. The sea is not where it should be: east of the village it stands upright, a green wall of water three houses high, holding still as glass. The light that comes through it is aquarium light, and it lies on everything.\n\nYou are not drowned. That appears to have been somebody's decision.\n\nA board has been nailed to a post at the head of the path."]
            },
            {
              "action": "setlocationdescription",
              "parameters": ["2", "One street of grey stone houses with their doors standing open. Nobody has gone through those doorways in a long while — the dust on the sills is unmarked, and lies thick and even, like something that has been allowed to finish.\n\nNothing here is broken. That is worse than if it were.\n\nNorth stands a squat tower. East, a schoolhouse with its windows steamed on the inside. West, an orchard wall."]
            },
            {
              "action": "setlocationdescription",
              "parameters": ["3", "Inside the tower it smells of rope and salt. The bell hangs in its frame above you, mouth down, big as a bathtub. The rope comes to a stop at chest height, spliced and waiting, with old grease on it where hands went.\n\nThrough the eastern arch: the quay, and above the quay, the standing wave."]
            },
            {
              "action": "setlocationdescription",
              "parameters": ["5", "Apple trees in wet rows, and the rain that was falling when everything stopped is falling still: every drop a bead of glass held at the height it had got to, motionless, catching what light there is. Walking here means going carefully between them, and you will not manage it perfectly, and each one you touch comes apart on your sleeve without a sound.\n\nNorth, the ground rises to a wellhead."]
            },
            {
              "action": "setlocationdescription",
              "parameters": ["6", "A short stone quay with a boat still tied to it, and over both of them the wave — sheer, standing, close enough to put your hand on, with three fish in it turned to face the village. Everything on the quay is green with the light coming through.\n\nAn iron hook is set into the wall at head height. It is empty, and there is soot on the stone above it."]
            }
          ]
        },
        {
          "interactionId": "bell-already",
          "if": ["bell_rung"],
          "triggers": ["ring the bell", "ring bell", "*ring the bell*", "pull the rope", "pull rope", "*pull the rope*", "toll the bell", "*toll the bell*"],
          "actions": [
            {
              "action": "describe",
              "parameters": ["You put your hand on the rope. The bell is still going, so far down in itself that it is more of a feeling in your teeth than a sound. It has been rung. Ambroke heard it.\n\nSomething else here is still asleep."]
            }
          ]
        },
        {
          "interactionId": "bell-ring",
          "triggers": ["ring the bell", "ring bell", "*ring the bell*", "pull the rope", "pull rope", "*pull the rope*", "toll the bell", "*toll the bell*"],
          "actions": [
            {
              "action": "describe",
              "parameters": ["The rope is colder than the room. You pull, and nothing happens, and you pull again with your whole weight —\n\nand the bell turns over and speaks, once, enormously, into a village that has not been spoken to in a very long time.\n\nDust lifts off every sill in Ambroke at the same instant and hangs there. Out on the quay, in the standing water, three fish turn to face the sound.\n\nSomething in the place is awake now and listening back."]
            },
            { "action": "addcondition", "parameters": ["bell_rung"] }
          ]
        }
      ]
    },

    {
      "index": 4,
      "name": "The Schoolhouse",
      "description": "Forty desks, and on each desk a slate, and on each slate the same letters practised in the same round hand. The windows are steamed on the inside, which means it was warm in here when it stopped.\n\nAt the front, a larger slate holds a list of names in the teacher's careful writing. Forty-one of them. The last is unfinished — two letters and a stop, as though the chalk had been set down so she could listen to something.\n\nThe chalk is still on the ledge.",
      "connections": { "west": 2 },
      "interactions": [
        {
          "interactionId": "names-already",
          "if": ["names_read"],
          "triggers": ["read the names", "read names", "*read the names*", "read the slate", "*read the slate*", "*read the list*", "*the forty-one*", "*read them aloud*"],
          "actions": [
            {
              "action": "describe",
              "parameters": ["You have already read them. The room is different now in the way a room is different once you know what it was for."]
            }
          ]
        },
        {
          "interactionId": "names-read",
          "triggers": ["read the names", "read names", "*read the names*", "read the slate", "*read the slate*", "*read the list*", "*the forty-one*", "*read them aloud*"],
          "actions": [
            {
              "action": "describe",
              "parameters": ["You read them out. Not in your head — aloud, because a list of names read silently is just handwriting.\n\nAgnes Loam. Peter Loam. Thomas Wry. Hester Wry. Small Dan Wry. Bell Carraway, and her brother, and the brother's dog, who is on the list because she made a fuss until he was. Forty of them, and then the forty-first, which is two letters and a full stop: Mi.\n\nYou say 'Mi' into the quiet, and it does not sound like nothing. It sounds like a name that was going to be finished.\n\nSomewhere north of here the dust has not come down yet."]
            },
            { "action": "addcondition", "parameters": ["names_read"] }
          ]
        },
        {
          "interactionId": "slate-sign",
          "triggers": ["write my name", "*write my name*", "*write your name*", "sign the slate", "*sign the slate*", "take the chalk", "*the chalk*", "*finish the name*", "write", "*add my name*"],
          "actions": [
            {
              "action": "describe",
              "parameters": ["The chalk is soft and leaves more of itself than you expect. You do not finish her name — that is not yours to finish — but you put a mark of your own below the list, where the teacher would have gone on.\n\nThere are other marks down there. Some are older than yours by a good deal. None of them are hers."]
            },
            { "action": "addcondition", "parameters": ["slate_marked"] },
            {
              "action": "setlocationdescription",
              "parameters": ["4", "Forty desks, and on each desk a slate, and on each slate the same letters practised in the same round hand. The windows are steamed on the inside, which means it was warm in here when it stopped.\n\nAt the front, a larger slate holds a list of names in the teacher's careful writing. Forty-one of them. The last is unfinished — two letters and a stop: Mi.\n\nBelow the list, where the teacher would have gone on, other hands have left marks. Some are grey with age. At least one is white and recent and still has chalk-dust under it on the floor.\n\nThe chalk is still on the ledge."]
            }
          ]
        }
      ]
    },

    {
      "index": 5,
      "name": "The Orchard",
      "description": "Apple trees in wet rows, and the rain that was falling when everything stopped is falling still: every drop a bead of glass held at the height it had got to, motionless, catching what light there is. Walking here means going carefully between them, and you will not manage it perfectly, and each one you touch comes apart on your sleeve without a sound.\n\nNorth, the ground rises to a wellhead.",
      "connections": { "east": 2, "north": 7 },
      "interactions": [
        {
          "interactionId": "orchard-apple",
          "triggers": ["take an apple", "pick an apple", "*pick an apple*", "*take an apple*", "*the apples*", "eat an apple", "*pick an apple*", "*apple from the tree*"],
          "actions": [
            {
              "action": "describe",
              "parameters": ["You pick one. It comes away with the small clean sound of a thing that was ready to be picked and then had to wait."]
            },
            { "action": "additems", "parameters": ["stopped apple"] }
          ]
        }
      ]
    },

    {
      "index": 6,
      "name": "The Quay",
      "description": "A short stone quay with a boat still tied to it, and over both of them the wave — sheer, standing, close enough to put your hand on, with three fish in it turned to face the village. Everything on the quay is green with the light coming through.\n\nAn iron hook is set into the wall at head height. It is empty, and there is soot on the stone above it.",
      "connections": { "west": 3 },
      "isExit": true,
      "monster": "grey heron",
      "interactions": [
        {
          "interactionId": "the-turning",
          "if": ["has_lamp", "bell_rung", "names_read"],
          "triggers": ["hang the lamp", "*hang the lamp*", "light the lamp", "*light the lamp*", "*hang the lantern*", "*lamp on the hook*", "put the lamp on the hook", "*hang it on the hook*"],
          "actions": [
            {
              "action": "describe",
              "parameters": ["The lamp settles onto the hook as though the hook had been made for it, which it was. The wick catches on the second try.\n\nThen a sound like a held breath being let go, from everywhere at once — and the wave, which has not moved in the time it takes for dust to lie down, leans.\n\nIt comes down slowly, for something that size. Green light swings across the lane and the orchard and the forty desks. Water goes up the street ankle-deep and comes back out again, taking the dust with it, leaving weed on the doorsteps and one small fish on the step of the schoolhouse, which flips twice and is gone.\n\nAnd then the ordinary noise of the sea, which you did not know you had been missing until it came back.\n\nBehind you the bell is still ringing itself quietly down to nothing."]
            },
            { "action": "removeitems", "parameters": ["drowned lamp"] },
            { "action": "removecondition", "parameters": ["has_lamp"], "scope": "player" },
            { "action": "addcondition", "parameters": ["wave_fallen"] },
            {
              "action": "setlocationdescription",
              "parameters": ["1", "Black stones running down to the sea — the ordinary sea, breathing in and out, doing what it does. The tideline is an honest mess of weed and rope and one blue plastic crate. It smells of iodine and diesel and cold.\n\nThe board is still nailed to its post at the head of the path, gone soft with spray."]
            },
            {
              "action": "setlocationdescription",
              "parameters": ["2", "One street of grey stone houses in daylight. The doors still stand open, but the dust is off the sills — wind took some and the water took the rest, and there are gull prints on a windowsill where nothing has walked for years.\n\nSomewhere a shutter knocks, gets bored, knocks again.\n\nNorth, the tower. East, the schoolhouse. West, the orchard."]
            },
            {
              "action": "setlocationdescription",
              "parameters": ["3", "The bell is quiet now, and the iron frame hums faintly, the way iron does for a long time after. Salt water has run down the inside walls and dried into tidelines you can put a finger on.\n\nThe rope hangs at chest height, spliced and waiting, exactly as it did before.\n\nThe thought arrives whole, and not entirely as your own: a bell that was rung once can be rung again. The wave came down when it was called. It would go back up the same way, and Ambroke would be asleep again, and somebody else could be the one to wake it."]
            },
            {
              "action": "setlocationdescription",
              "parameters": ["5", "Apple trees in wet rows with the rain going through them properly, in lines, making noise on the leaves. The ground has gone soft. There are windfalls everywhere and all of them are fresh.\n\nNorth, the ground rises to a wellhead."]
            },
            {
              "action": "setlocationdescription",
              "parameters": ["6", "The quay, wet, with the sea moving against it at the height a sea is supposed to be. The boat sits on the water and pulls at its line like it has been waiting to.\n\nThe lamp burns in the iron hook above — small, steady, and in daylight completely pointless. Nobody is going to put it out."]
            }
          ]
        },
        {
          "interactionId": "lamp-wont-hold",
          "if": ["has_lamp"],
          "triggers": ["hang the lamp", "*hang the lamp*", "light the lamp", "*light the lamp*", "*hang the lantern*", "*lamp on the hook*", "put the lamp on the hook", "*hang it on the hook*"],
          "actions": [
            {
              "action": "describe",
              "parameters": ["You hang it on the hook and put a flame to the wick. It takes, goes blue, and drowns — there is no other word for it — as though the air itself were water.\n\nThe lamp is not the first thing. Ambroke is still asleep: it has not been called, or it has not been counted. A bell has a village's attention. A list of names is what there is to say to it.\n\nYou take the lamp down again. It is still warm."]
            }
          ]
        },
        {
          "interactionId": "lamp-none",
          "triggers": ["hang the lamp", "*hang the lamp*", "light the lamp", "*light the lamp*", "*hang the lantern*", "*lamp on the hook*", "put the lamp on the hook", "*hang it on the hook*"],
          "actions": [
            {
              "action": "describe",
              "parameters": ["Your hands are empty and the hook stays empty. There was a lamp — the soot above the hook is proof of it — and the keeper of it went into the well at the top of the orchard, the last time anybody in Ambroke chose anything."]
            }
          ]
        },
        {
          "interactionId": "boat-free",
          "if": ["wave_fallen"],
          "triggers": ["the boat", "untie the boat", "*untie the boat*", "board the boat", "*get in the boat*", "row", "*take the oar*", "*the oar*", "*the boat*"],
          "actions": [
            {
              "action": "describe",
              "parameters": ["The line comes off the bollard in one movement, the way a rope does when it is glad. The boat is dry inside. Under the thwart, wrapped in sacking against exactly this long a wait, is one oar.\n\nOne oar is enough to scull with, if you know how. If you do not, you will learn out there, which is how everybody learned."]
            },
            { "action": "additems", "parameters": ["oar"] }
          ]
        },
        {
          "interactionId": "boat-under-wave",
          "triggers": ["the boat", "untie the boat", "*untie the boat*", "board the boat", "*get in the boat*", "row", "*take the oar*", "*the oar*", "*the boat*"],
          "actions": [
            {
              "action": "describe",
              "parameters": ["The boat is tied under a wall of standing water. You can get into it. You can sit in it, and look up through the green at the fish that have been going nowhere for years, and understand with great clarity that if you cast off you will simply be a thing inside a wave when it decides to come down.\n\nYou get out again."]
            }
          ]
        },
        {
          "interactionId": "quay-touch-wave",
          "ifNot": ["wave_fallen"],
          "triggers": ["touch the wave", "*touch the wave*", "*touch the water*", "*put your hand*", "*touch it*"],
          "actions": [
            {
              "action": "describe",
              "parameters": ["It is cold, and it gives — it is water, it is only water — and it does not come apart or come down. Your hand goes in to the wrist. When you take it out, it is wet, and that is somehow the most frightening thing that has happened to you today.\n\nOne of the fish has turned to look at you."]
            }
          ]
        }
      ]
    },

    {
      "index": 7,
      "name": "The Wellhead",
      "description": "A low wall of mossed brick around a black circle. The bucket is up on its rope and has been dry for years.\n\nA long way down — further than a village well has any business going — something gives back a very small amount of light.\n\nThis is where Ambroke's lamp-keeper went in, the last time anybody here chose anything.",
      "connections": { "south": 5 },
      "interactions": [
        {
          "interactionId": "lamp-have",
          "if": ["has_lamp"],
          "triggers": ["lower the bucket", "*lower the bucket*", "climb down", "*down the well*", "*into the well*", "*the well*", "*the bucket*", "*look in the well*"],
          "actions": [
            {
              "action": "describe",
              "parameters": ["The bucket is up and the well is just a well. The lamp is looped over your arm, dripping cold water down your side."]
            }
          ]
        },
        {
          "interactionId": "lamp-gone",
          "if": ["lamp_lit"],
          "triggers": ["lower the bucket", "*lower the bucket*", "climb down", "*down the well*", "*into the well*", "*the well*", "*the bucket*", "*look in the well*"],
          "actions": [
            {
              "action": "describe",
              "parameters": ["Nothing down there now but water and the cold smell of brick. What was giving back the light is on the quay, burning, where it was always supposed to be."]
            }
          ]
        },
        {
          "interactionId": "lamp-take",
          "ifNot": ["has_lamp", "lamp_lit"],
          "triggers": ["lower the bucket", "*lower the bucket*", "climb down", "*down the well*", "*into the well*", "*the well*", "*the bucket*", "*look in the well*"],
          "actions": [
            {
              "action": "describe",
              "parameters": ["You put the bucket down on its rope, hand over hand, much further than you expect, until the rope goes slack and then taut in a different way — the weight of something caught.\n\nWhat comes up is a keeper's storm-lamp, brass gone green, glass unbroken, full of oil, with a strand of weed round the handle. It is not rusted through. It has waited the way everything in Ambroke has waited.\n\nYou do not look too closely at what else is down there, and nothing down there asks you to."]
            },
            { "action": "additems", "parameters": ["drowned lamp"] },
            { "action": "addcondition", "parameters": ["has_lamp"], "scope": "player" }
          ]
        }
      ]
    }
  ]
}

